def hasMatch(s: str, p: str) -> bool:
    star_index = p.index('*')
    prefix = p[:star_index]
    suffix = p[star_index + 1:]
    prefix_length = len(prefix)
    suffix_length = len(suffix)
    max_start = len(s) - prefix_length - suffix_length

    for start in range(max_start + 1):
        if s[start:start + prefix_length] == prefix:
            if s[start + prefix_length:start + prefix_length + suffix_length] == suffix:
                return True

    return False

