from typing import List

def largestInteger(nums: List[int], k: int) -> int:
    from collections import defaultdict

    count = defaultdict(int)
    n = len(nums)

    for i in range(n - k + 1):
        seen = set()  # Track unique elements in the current subarray
        for j in range(i, i + k):
            seen.add(nums[j])
        for num in seen:
            count[num] += 1  # Increment the count for each unique number in the subarray

    # Find the largest integer that appears in exactly one subarray
    largest = -1
    for num, cnt in count.items():
        if cnt == 1:
            largest = max(largest, num)

    return largest

