def longestSubsequence(nums: List[int]) -> int:
    n = len(nums)
    dp = [1] * n  # dp[i] = length of the longest valid subsequence ending at i
    max_length = 1

    for i in range(n):
        for j in range(i):
            abs_diff = abs(nums[i] - nums[j])
            valid = True
            # Check if the subsequence can be extended
            for k in range(j + 1, i):
                if abs_diff < abs(nums[k] - nums[k - 1]):
                    valid = False
                    break
            if valid:
                dp[i] = max(dp[i], dp[j] + 1)
        max_length = max(max_length, dp[i])

    return max_length

